#!/usr/bin/env node
/**
 * check-publish-hygiene.mjs
 *
 * Publish-hygiene gate (originally BUG-AGENTMCP-003 P0): a published package
 * must ship its declared entry points and MUST NOT ship tests / dev-config.
 *
 * PUBLISH-FROM-DIST MODEL: the workspace publishes each package from its built
 * artifact directory ({projectRoot}/dist), whose package.json is generated by
 * the `dist-manifest` step (tools/nx-plugins/build/executors/manifest). So this
 * gate packs FROM {projectRoot}/dist — the exact directory `nx-release-publish`
 * packs from (packageRoot:{projectRoot}/dist) — and reads the DIST manifest
 * (rebased, resolved) as the source of declared entry points.
 *
 * For each package this:
 *   1. Confirms the package has actually been built + versioned (its dist dir
 *      AND dist/package.json exist) — a missing prerequisite is a hard failure,
 *      never a silent skip.
 *   2. Runs `npm pack --dry-run --json` FROM the dist dir (real npm packing
 *      rules: always-included package.json/README/LICENSE/main, no `files`
 *      allowlist now that dist is the package root).
 *   3. Asserts the resulting tarball file list:
 *        a. contains ZERO test/dev-config entries.
 *        b. DOES contain every main/module/typings/exports target the DIST
 *           package.json declares — a missing target = unimportable publish.
 *
 * Usage:
 *   node check-publish-hygiene.mjs <projectRoot>          # per-project (executor path)
 *   node check-publish-hygiene.mjs <projectRoot> --json
 *   node check-publish-hygiene.mjs                        # default legacy package set
 *
 * Exit code is the SOLE source of truth: 0 = clean, 1 = at least one violation
 * (or a missing build/manifest). Never gate on the human-readable text output.
 */

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const findRoot = (d) => { while (d !== path.dirname(d)) { if (existsSync(path.join(d, 'nx.json'))) return d; d = path.dirname(d); } return d; };
const REPO_ROOT = findRoot(__dirname);

// Legacy default set (standalone/no-arg mode). Extend as needed; the per-project
// mode (an explicit projectRoot arg) is the primary, executor-driven path.
const DEFAULT_PACKAGE_ROOTS = [
  'entrypoint/agent-mcp',
  'packages/agent/agent-base-types',
  'packages/agent/agent-generator-plugin',
  'packages/agent/agent-plugin-budget',
  'packages/agent/agent-plugin-sanitize',
];

// A package's own shipped payload may legitimately contain test/dev-config-shaped
// filenames (an Nx generator ships scaffold TEMPLATES under __files__/, e.g.
// `skeleton.test.ts__tmpl__`). Those are data, not the package's own bloat.
const EXEMPT_PATH_TESTS = [(p) => /\/__files__\//.test(p)];

const FORBIDDEN_PATTERNS = [
  { label: '__tests__ directory', test: (p) => /(^|\/)__tests__\//.test(p) },
  { label: '*.test.*', test: (p) => /\.test\.[^/]+$/.test(p) },
  { label: '*.spec.*', test: (p) => /\.spec\.[^/]+$/.test(p) },
  { label: '*.e2e.*', test: (p) => /\.e2e\.[^/]+$/.test(p) },
  { label: 'vite.config.*', test: (p) => /(^|\/)vite\.config\.[^/]+$/.test(p) },
  { label: 'project.json', test: (p) => /(^|\/)project\.json$/.test(p) },
  { label: 'tsconfig*.json', test: (p) => /(^|\/)tsconfig[^/]*\.json$/.test(p) },
  { label: 'coverage/', test: (p) => /(^|\/)coverage\//.test(p) },
];

function stripLeadingDotSlash(p) {
  return p.replace(/^\.\//, '');
}

function collectExpectedTargets(pkgJson) {
  const targets = [];
  if (pkgJson.main) targets.push(['main', pkgJson.main]);
  if (pkgJson.module) targets.push(['module', pkgJson.module]);
  if (pkgJson.typings) targets.push(['typings', pkgJson.typings]);
  if (pkgJson.types) targets.push(['types', pkgJson.types]);
  if (pkgJson.exports) {
    const flatten = (obj, segments) => {
      for (const [key, value] of Object.entries(obj)) {
        const segment = key === '.' ? [] : [key.replace(/^\.\//, '')];
        const nextSegments = [...segments, ...segment];
        if (typeof value === 'string') {
          targets.push([`exports${nextSegments.length ? '.' + nextSegments.join('.') : ''}`, value]);
        } else if (value && typeof value === 'object') {
          flatten(value, nextSegments);
        }
      }
    };
    flatten(pkgJson.exports, []);
  }
  return targets.filter(([, target]) => typeof target === 'string' && target.startsWith('.'));
}

/**
 * @param {string} projectRoot workspace-relative project root (dist is {projectRoot}/dist)
 */
function checkPackage(projectRoot) {
  const distDir = path.join(REPO_ROOT, projectRoot, 'dist');
  const pkgJsonPath = path.join(distDir, 'package.json');
  const result = { name: projectRoot, distDir: path.relative(REPO_ROOT, distDir), ok: false, errors: [], totalFiles: 0, forbiddenHits: [], checkedTargets: [] };

  if (!existsSync(distDir)) {
    result.errors.push(`built output missing: ${result.distDir} — run \`nx build\` (a missing build must fail, never pass).`);
    return result;
  }
  if (!existsSync(pkgJsonPath)) {
    result.errors.push(`${result.distDir}/package.json missing — run the \`dist-manifest\` target (it versions the dist).`);
    return result;
  }

  const pkgJson = JSON.parse(readFileSync(pkgJsonPath, 'utf8'));
  result.name = pkgJson.name || projectRoot;

  const packResult = spawnSync('npm', ['pack', '--dry-run', '--json'], { cwd: distDir, encoding: 'utf8' });
  if (packResult.status !== 0) {
    result.errors.push(`npm pack --dry-run exited ${packResult.status} in ${result.distDir}: ${packResult.stderr?.trim() || packResult.stdout?.trim() || '(no output)'}`);
    return result;
  }
  let parsed;
  try { parsed = JSON.parse(packResult.stdout); } catch (err) { result.errors.push(`could not parse npm pack --json output: ${err.message}`); return result; }

  const allFiles = (parsed[0]?.files ?? []).map((f) => f.path);
  result.totalFiles = allFiles.length;
  const files = allFiles.filter((p) => !EXEMPT_PATH_TESTS.some((t) => t(p)));

  for (const { label, test } of FORBIDDEN_PATTERNS) {
    const hits = files.filter(test);
    if (hits.length > 0) result.forbiddenHits.push({ label, hits });
  }

  const expected = collectExpectedTargets(pkgJson);
  for (const [label, target] of expected) {
    const present = allFiles.includes(stripLeadingDotSlash(target));
    result.checkedTargets.push({ label, target, present });
    if (!present) result.errors.push(`declared "${label}": "${target}" is NOT in the packed tarball — published package would be broken/unimportable.`);
  }
  if (result.forbiddenHits.length > 0) {
    for (const { label, hits } of result.forbiddenHits) result.errors.push(`forbidden pattern "${label}" matched ${hits.length} file(s): ${hits.join(', ')}`);
  }

  result.ok = result.errors.length === 0;
  return result;
}

function main() {
  const args = process.argv.slice(2);
  const asJson = args.includes('--json');
  const projectRoots = args.filter((a) => !a.startsWith('--'));
  const roots = projectRoots.length > 0 ? projectRoots : DEFAULT_PACKAGE_ROOTS;

  const results = roots.map(checkPackage);
  const anyFailed = results.some((r) => !r.ok);

  if (asJson) {
    process.stdout.write(JSON.stringify({ ok: !anyFailed, results }, null, 2) + '\n');
  } else {
    for (const r of results) {
      console.log(`[${r.ok ? 'PASS' : 'FAIL'}] ${r.name} (${r.distDir}) — ${r.totalFiles} file(s) in tarball`);
      for (const t of r.checkedTargets) console.log(`    ${t.present ? '✓' : '✗'} ${t.label}: ${t.target}`);
      for (const err of r.errors) console.log(`    ERROR: ${err}`);
    }
    console.log('');
    console.log(anyFailed ? 'publish-hygiene check: FAILED' : 'publish-hygiene check: all packages clean');
  }
  process.exit(anyFailed ? 1 : 0);
}

main();
